/* util.LookUpHTML5EntityByName */
const MarkEntity *mark_entity_lookup(CuStr name)
{
    size_t lo = 0;
    size_t hi = MARK_ENTITY_COUNT;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        const MarkEntity *e = &entities[mid];
        size_t n = name.len < e->name_len ? name.len : e->name_len;
        int c = memcmp(name.ptr, e->name, n);

        if (c == 0) {
            if (name.len == e->name_len) return e;
            c = name.len < e->name_len ? -1 : 1;
        }
        if (c < 0) hi = mid;
        else lo = mid + 1;
    }
    return NULL;
}
